css:
/* login form by rajesh_4474 */
@keyframes gradientBackground {
  0% {
    background: linear-gradient(45deg, #ff7e5f, #feb47b);
  }
  50% {
    background: linear-gradient(45deg, #58bc82, #45a56b);
  }
  100% {
    background: linear-gradient(45deg, #ff7e5f, #feb47b);
  }
}

.login-form {
  max-width: 420px;
  width: 100%;
  padding: 40px;
  background: rgba(255, 255, 255, 0.9);
  border-radius: 12px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.1);
  animation: fadeIn 1.5s ease-out;
}

.form-heading {
  text-align: center;
  color: #333;
  font-size: 2rem;
  font-weight: 600;
  margin-bottom: 25px;
  letter-spacing: 1px;
  text-transform: uppercase;
}

.input-group {
  position: relative;
  margin-bottom: 20px;
}

.input-group .label {
  position: absolute;
  top: -16px;
  left: 12px;
  font-size: 12px;
  color: #58bc82;
  font-weight: 600;
  transition: all 0.3s ease;
  opacity: 0.7;
}

.input-group input {
  width: 100%;
  padding: 15px 20px;
  font-size: 1rem;
  color: #333;
  background-color: #f5f5f5;
  border: 2px solid #ddd;
  border-radius: 10px;
  outline: none;
  transition: all 0.3s ease;
}

.input-group input:focus {
  border-color: #58bc82;
  box-shadow: 0 0 10px rgba(88, 188, 130, 0.4);
}

.input-group input:focus + .label {
  top: -20px;
  font-size: 11px;
  color: #58bc82;
  opacity: 1;
}

.forgot-password {
  text-align: right;
  margin-bottom: 20px;
}

.forgot-password a {
  font-size: 14px;
  color: #58bc82;
  text-decoration: none;
  transition: color 0.3s ease;
}

.forgot-password a:hover {
  color: #45a56b;
}

.submit {
  width: 100%;
  padding: 15px;
  background-color: #58bc82;
  color: #fff;
  border: none;
  border-radius: 30px;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s ease;
}

.submit:hover {
  background-color: #45a56b;
  transform: translateY(-2px);
  box-shadow: 0 5px 20px rgba(88, 188, 130, 0.3);
}

.signup-link {
  text-align: center;
  font-size: 14px;
  color: #333;
}

.signup-link a {
  color: #58bc82;
  text-decoration: none;
  font-weight: 600;
  transition: color 0.3s ease;
}

.signup-link a:hover {
  color: #45a56b;
}

@keyframes fadeIn {
  0% {
    opacity: 0;
    transform: scale(0.9);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

@media (max-width: 480px) {
  .login-form {
    padding: 30px;
    width: 90%;
  }
}
